function showEvaluationInspector(item,action=null){if(!item)return;$("#evaluationInspectorMeta").textContent="INTERACTIVE TEST / 验证详情";$("#evaluationInspectorCode").textContent=item[0];$("#evaluationInspectorTitle").textContent=item[1];$("#evaluationInspectorText").textContent=item[2];$("#evaluationInspectorFacts").innerHTML=item.slice(3).map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join("");const button=$("#evaluationInspectorAction");button.classList.toggle("hidden",!action);button.onclick=action||null;$("#evaluationInspector").classList.remove("pulse") ;requestAnimationFrame(()=>$("#evaluationInspector").classList.add("pulse"))}
function openValidationInRisk(sample){const domain=sample[1],id=sample[0];const scenarioId=id==="F-01"?"fire-evidence":id==="F-05"?"fire-measures":domain==="fire"?"fire-main":id==="G-04"?"cold-start":id==="G-05"?"hidden-rule-ventilation":id==="G-02"?"trace-source":"gas-main";return async()=>{await selectDomain(domain,false);await selectScenario(scenarioId,false);$("#questionInput").value=sample[2];switchModule("risk");runAnalysis("trace");showToast(`已载入验证样本 ${id}`)}}
function renderEvaluation(domain=state.activeDomain){const d=evaluationData[domain];if(!d)return;state.evaluationRunToken++;$("#evaluationDomainLabel").textContent=d.label;$("#evaluationRunState").textContent="待运行";$("#runEvaluation").classList.remove("running","complete");$("#runEvaluation").disabled=false;$$('[data-eval-step]').forEach(x=>x.classList.remove("active","complete"));$("#sampleStats").innerHTML=d.stats.map((x,i)=>`<button data-eval-sample="${i}" type="button"><strong>${x[0]}</strong><b>${x[1]}</b><p>${x[2]}</p><em>查看样本 →</em></button>`).join("");$("#metricGrid").innerHTML=evaluationMetrics.map((x,i)=>`<button data-eval-metric="${i}" type="button"><div><span>${x[3]}</span><h3>${x[0]}</h3></div><dl><div><dt>申报目标</dt><dd>${x[1]}</dd></div><div><dt>离线实测</dt><dd>${x[2]}</dd></div></dl><em><i></i>达标</em></button>`).join("");$$('[data-eval-sample]').forEach(b=>b.onclick=()=>{const x=d.stats[Number(b.dataset.evalSample)];$$('[data-eval-sample]').forEach(x=>x.classList.toggle("active",x===b));showEvaluationInspector([`SAMPLE-${String(Number(b.dataset.evalSample)+1).padStart(2,"0")}`,`${d.label} · ${x[1]}`,x[2],["当前数量",x[0]],["数据性质","人工整理演示样本"]])});$$('[data-eval-metric]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.evalMetric),m=evaluationMetrics[i];$$('[data-eval-metric]').forEach(x=>x.classList.toggle("active",x===b));showEvaluationInspector([evaluationMetricDetails[i][0],m[0],evaluationMetricDetails[i][1],["申报目标",m[1]],["原型离线结果",m[2]],...evaluationMetricDetails[i].slice(2)])});renderValidationTable(state.evaluationFilter);showEvaluationInspector(["READY-01",`${d.label}测试已就绪`,"可点击样本、划分、方法、指标、验收问题和测试步骤查看细节，或运行一次固定样本复现流程。",["验证问题","5条 / 场景"],["执行方式","冻结样本离线复现"]])}
function renderValidationTable(filter="all"){state.evaluationFilter=filter;$$('[data-eval-filter]').forEach(b=>b.classList.toggle("active",b.dataset.evalFilter===filter));const rows=validationSamples.filter(x=>filter==="all"||x[1]===filter);$("#validationTable").innerHTML=`<div class="validation-head"><b>编号</b><b>验证问题</b><b>验收关注点</b><b>结果</b></div>${rows.map(x=>`<button data-validation-id="${x[0]}" type="button"><span>${x[0]}</span><p>${x[2]}</p><em>${x[3]}</em><strong><i></i>${x[4]}</strong></button>`).join("")}`;$$('[data-validation-id]').forEach(b=>b.onclick=()=>{const sample=validationSamples.find(x=>x[0]===b.dataset.validationId);$$('[data-validation-id]').forEach(x=>x.classList.toggle("active",x===b));showEvaluationInspector([sample[0],sample[2],`验收关注点：${sample[3]}。点击右侧按钮可将对应演示场景载入风险研判页。`,["所属场景",sample[1]==="fire"?"煤自燃":"通风瓦斯"],["离线结果",sample[4]]],openValidationInRisk(sample))})}
async function runEvaluation(){const button=$("#runEvaluation"),token=++state.evaluationRunToken;button.disabled=true;button.classList.add("running");button.classList.remove("complete");for(let i=0;i<evaluationStepDetails.length;i++){if(token!==state.evaluationRunToken)return;$$('[data-eval-step]').forEach((x,j)=>{x.classList.toggle("active",j===i);x.classList.toggle("complete",j<i)});$("#evaluationRunState").textContent=`${i+1} / 5`;showEvaluationInspector(evaluationStepDetails[i]);await new Promise(r=>setTimeout(r,520))}if(token!==state.evaluationRunToken)return;$$('[data-eval-step]').forEach(x=>{x.classList.remove("active");x.classList.add("complete")});button.disabled=false;button.classList.remove("running");button.classList.add("complete");$("#evaluationRunState").textContent="6项指标达标";showEvaluationInspector(["RUN-PASS",`${evaluationData[state.activeDomain].label}离线复现完成`,"固定演示样本已完成五阶段验证，六项指标达到申报目标；结果仅代表当前人工整理原型测试集。",["指标结果","6 / 6 达标"],["验证问题","5 / 5 通过"],["结果边界","非矿井生产效果"]]);showToast("当前场景离线验证流程已完成")}
async function selectDomain(domain,analyze=true){if(!evaluationData[domain])return;state.activeDomain=domain;$$('[data-domain]').forEach(b=>b.classList.toggle("active",b.dataset.domain===domain));const config=overviewCaseConfigs[domain];$("#contextObject").textContent=config.context;$("#overviewCaseKicker").textContent=config.kicker;$("#overviewCaseTitle").textContent=config.title;renderOverviewCase(domain);renderPresetQuestions();renderEvaluation(domain);const target=state.scenarios.find(x=>x.id===(domain==="fire"?"fire-main":"gas-main"));if(target)await selectScenario(target.id,analyze);showToast(domain==="fire"?"已切换至煤自燃征兆场景":"已切换至通风瓦斯场景")}
async function resetWorkspace(targetModule="overview"){closeArchivePreview();state.activeDomain="gas";$$('[data-domain]').forEach(b=>b.classList.toggle("active",b.dataset.domain==="gas"));renderOverviewCase();renderPresetQuestions();renderEvaluation("gas");showOverviewSolution("graph");state.kgMode="all";state.source="rules";state.filter="all";state.constructionView="pipeline";state.corpusFilter="全部";$("#kgSearchInput").value="";if($("#corpusSearch"))$("#corpusSearch").value="";setActive($(".tool-chip[data-kg-mode='all']"),".tool-chip");renderKg("all");setActive($(".source-item[data-source='rules']"),".source-item");setActive($(".table-filter [data-filter='all']"),".table-filter button");const corpusAll=$("[data-corpus-filter='全部']");if(corpusAll)setActive(corpusAll,"[data-corpus-filter]");if(state.knowledgeBase){renderCorpus();switchConstructionView("pipeline")}renderGovernance();showGovernanceStage("align");setActive($(".collab-tab[data-collab-mode='retrieve']"),".collab-tab");renderCollaboration("retrieve");switchCollabStage("fusion");switchCollabView("flow");if(state.scenarios.length){await selectScenario("gas-main",false);switchView("graph");runAnalysis("trace")}switchModule(targetModule);$$('.overview-workspace,.left-panel,.right-panel,.knowledge-sidebar,.entity-detail-panel,.quality-panel,.corpus-panel,.construction-main,.source-inspector-panel,.collab-grid>.panel').forEach(x=>x.scrollTop=0);showToast("已恢复默认视图")}
async function initialize(){bindEvents();bindCollabEvents();bindConstructionEvents();renderKg("all");renderGovernance();renderCollaboration("retrieve");try{const [p,kb]=await Promise.all([fetchJson("/api/scenarios"),fetchJson("/data/knowledge-base.json")]);state.scenarios=p.scenarios;state.knowledgeBase=kb;renderConstruction();renderOverviewCase();renderEvaluation("gas");renderPresetQuestions();await selectScenario("gas-main",false);runAnalysis("trace")}catch(e){console.error(e);showToast("数据加载失败，请确认 Python 服务正在运行")}}
