  $$('[data-eval-step]').forEach(b=>b.onclick=()=>{$$('[data-eval-step]').forEach(x=>x.classList.toggle("active",x===b));showEvaluationInspector(evaluationStepDetails[Number(b.dataset.evalStep)])});
