function updateGraphLines(){
  if(!state.activeScenario||!$("#nodeLayer").children.length)return;
  const c=$("#graphCanvas").getBoundingClientRect(),map={};
  $$(".graph-node").forEach(n=>{
    const r=n.getBoundingClientRect();
    map[n.dataset.id]={x:r.left-c.left+r.width/2,y:r.top-c.top+r.height/2,left:r.left-c.left,right:r.right-c.left,top:r.top-c.top,bottom:r.bottom-c.top};
  });
  $("#edgeLayer").setAttribute("viewBox",`0 0 ${c.width} ${c.height}`);
  $("#edgeLayer").innerHTML=state.activeScenario.graph.edges.map(e=>{
    const a=map[e.from],b=map[e.to];if(!a||!b)return"";
    const x=(a.x+b.x)/2,baseY=(a.y+b.y)/2-8,labelWidth=Math.max(58,e.label.length*15),labelHeight=24;
    const overlaps=n=>x+labelWidth/2>n.left-7&&x-labelWidth/2<n.right+7&&baseY+labelHeight/2>n.top-7&&baseY-labelHeight/2<n.bottom+7;
    const y=overlaps(a)||overlaps(b)?Math.max(20,Math.min(a.top,b.top)-16):baseY;
    return `<g><line class="edge-line ${e.predicted?"predicted":""}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/><text class="edge-label" x="${x}" y="${y}">${e.label}</text></g>`;
  }).join("");
}
