    await tourClick("[data-collab-view='graph']",token);await tourWait(900,token);await tourClick("[data-collab-stage='output']",token,380);await tourClick("#collabEvidenceList button:nth-child(1)",token);await tourClick("#collabEvidenceList button:nth-child(3)",token);await tourWait(1800,token);
    await tourClick("[data-domain='fire']",token,600);await tourWait(1600,token);await tourClick(".nav-item[data-module='risk']",token);await tourClick("[data-evidence-status='support']",token);await tourClick("[data-evidence-status='reverse']",token);await tourClick("[data-evidence-status='missing']",token);await tourClick(".view-button[data-view='timeline']",token);await tourClick("#timelineEvents .timeline-card:nth-of-type(3)",token);await tourWait(1800,token);
    await tourClick(".nav-item[data-module='governance']",token,420);await tourClick(".source-item[data-source='cases']",token);await tourClick(".table-filter [data-filter='review']",token);await tourClick(".pipeline-stage[data-pipeline-stage='quality']",token);await tourClick(".source-item[data-source='monitor']",token);await tourWait(1500,token);
